(function(){
  if (window.__dispInstalled__) return;
  window.__dispInstalled__ = true;
  var canvas = document.getElementById('dispCanvas');
  var ctx = canvas.getContext('2d');
  var i1Slider = document.getElementById('i1Slider');
  var i1Val = document.getElementById('i1Val');
  var out = document.getElementById('dispOut');
  var playBtn = document.getElementById('playBtn');
  var CX = canvas.width / 2, CY = canvas.height / 2;
  var D2R = Math.PI / 180;
  var running = false, pulse = 0;
  var COLORS = [
    { name: 'أحمر', n: 1.52, col: '#ef4444' },
    { name: 'برتقالي', n: 1.53, col: '#f97316' },
    { name: 'أصفر', n: 1.54, col: '#eab308' },
    { name: 'أخضر', n: 1.56, col: '#22c55e' },
    { name: 'أزرق', n: 1.58, col: '#3b82f6' },
    { name: 'بنفسجي', n: 1.60, col: '#8b5cf6' }
  ];
  var AP = [CX, CY - 150], BL = [CX - 110, CY + 115], BR = [CX + 110, CY + 115];
  var vL = [BL[0] - AP[0], BL[1] - AP[1]], vR = [BR[0] - AP[0], BR[1] - AP[1]];
  var Adeg = Math.acos((vL[0]*vR[0] + vL[1]*vR[1]) / (Math.hypot(vL[0],vL[1]) * Math.hypot(vR[0],vR[1]))) / D2R;
  var NL = [vL[1], -vL[0]], NR = [-vR[1], vR[0]];
  var lnl = Math.hypot(NL[0], NL[1]); NL = [NL[0]/lnl, NL[1]/lnl];
  var lnr = Math.hypot(NR[0], NR[1]); NR = [NR[0]/lnr, NR[1]/lnr];
  var NRout = [-NR[0], -NR[1]];
  var SCREENX = canvas.width - 52;
  window.simState = { i1: 45, nRed: 1.52, nViolet: 1.60, Dred: 0, Dvio: 0, spread: 0, Adeg: Adeg, time: 0, running: false };
  function norm(v){ var l = Math.hypot(v[0],v[1]) || 1; return [v[0]/l, v[1]/l]; }
  function rot(x, y, t){ var c = Math.cos(t), s = Math.sin(t); return [x*c - y*s, x*s + y*c]; }
  function refract(D, N, n1, n2){
    var cosI = D[0]*N[0] + D[1]*N[1];
    if (cosI < 0) return null;
    var sinI = Math.sqrt(Math.max(0, 1 - cosI*cosI));
    var sinR = sinI * n1 / n2;
    if (sinR > 1) return null;
    var r = Math.asin(sinR);
    var px = D[0] - cosI*N[0], py = D[1] - cosI*N[1];
    var pl = Math.hypot(px, py) || 1; px /= pl; py /= pl;
    return { dir: [Math.cos(r)*N[0] + Math.sin(r)*px, Math.cos(r)*N[1] + Math.sin(r)*py], r: r };
  }
  function intersectLine(p, d, a, b){
    var w = [b[0]-a[0], b[1]-a[1]];
    var r = [a[0]-p[0], a[1]-p[1]];
    var det = d[0]*w[1] - d[1]*w[0];
    if (Math.abs(det) < 1e-9) return null;
    var s = (r[0]*w[1] - r[1]*w[0]) / det;
    var u = (d[0]*r[1] - d[1]*r[0]) / det;
    if (s < 0) return null;
    return { p: [p[0] + s*d[0], p[1] + s*d[1]], u: u };
  }
  function compute(){
    var i1 = parseFloat(i1Slider.value);
    var D_in = rot(NL[0], NL[1], -i1*D2R);
    var I0 = [AP[0] + 0.45*(BL[0]-AP[0]), AP[1] + 0.45*(BL[1]-AP[1])];
    var start = [I0[0] - 330*D_in[0], I0[1] - 330*D_in[1]];
    var rays = [];
    for (var k = 0; k < COLORS.length; k++){
      var col = COLORS[k];
      var ref1 = refract(D_in, NL, 1, col.n);
      if (!ref1) continue;
      var hit1 = intersectLine(I0, ref1.dir, AP, BR);
      if (!hit1) continue;
      var sinI2 = Math.abs(ref1.dir[0]*NRout[1] - ref1.dir[1]*NRout[0]);
      var ref2 = refract(ref1.dir, NRout, col.n, 1);
      if (!ref2) continue;
      var Ddeg = i1 + ref2.r/D2R - Adeg;
      var tS = (SCREENX - hit1.p[0]) / ref2.dir[0];
      var sy = hit1.p[1] + tS*ref2.dir[1];
      rays.push({ col: col, I1: hit1.p, d2: ref2.dir, Ddeg: Ddeg, sy: sy, i2: Math.asin(Math.min(1,sinI2))/D2R, r1: ref1.r/D2R });
    }
    return { i1: i1, D_in: D_in, I0: I0, start: start, rays: rays };
  }
  function draw(){
    var R = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0b1220'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#64748b'; ctx.font = '13px sans-serif'; ctx.textAlign = 'right';
    ctx.fillText('الضوء الأبيض', 16, 22);
    ctx.fillText('الشاشة', canvas.width - 80, 22);
    ctx.strokeStyle = '#334155'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(SCREENX, 0); ctx.lineTo(SCREENX, canvas.height); ctx.stroke();
    ctx.fillStyle = '#e2e8f0'; ctx.strokeStyle = '#475569'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(AP[0], AP[1]); ctx.lineTo(BL[0], BL[1]); ctx.lineTo(BR[0], BR[1]); ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.font = '12px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('A = ' + Adeg.toFixed(1) + '°', CX, AP[1] - 10);
    ctx.strokeStyle = '#f8fafc'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(R.start[0], R.start[1]); ctx.lineTo(R.I0[0], R.I0[1]); ctx.stroke();
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1; ctx.setLineDash([4,4]);
    ctx.beginPath(); ctx.moveTo(R.I0[0], R.I0[1]); ctx.lineTo(R.I0[0] + 90*NL[0], R.I0[1] + 90*NL[1]); ctx.stroke();
    ctx.setLineDash([]);
    var yMin = 1e9, yMax = -1e9;
    for (var k = 0; k < R.rays.length; k++){
      var ray = R.rays[k];
      if (ray.sy < yMin) yMin = ray.sy;
      if (ray.sy > yMax) yMax = ray.sy;
      ctx.strokeStyle = ray.col.col; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(R.I0[0], R.I0[1]); ctx.lineTo(ray.I1[0], ray.I1[1]); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ray.I1[0], ray.I1[1]); ctx.lineTo(SCREENX, ray.sy); ctx.stroke();
      ctx.fillStyle = ray.col.col;
      ctx.fillRect(SCREENX - 7, ray.sy - 6, 14, 12);
      ctx.font = '11px sans-serif'; ctx.textAlign = 'left';
      ctx.fillText(ray.col.name, SCREENX + 14, ray.sy + 4);
    }
    if (yMin < yMax){
      for (var yy = Math.floor(yMin); yy <= Math.ceil(yMax); yy += 2){
        var f = (yy - yMin) / (yMax - yMin);
        var c1 = R.rays[0].col.col, c2 = R.rays[R.rays.length - 1].col.col;
        var idx = Math.round(f * (R.rays.length - 1));
        if (idx < 0) idx = 0; if (idx >= R.rays.length) idx = R.rays.length - 1;
        ctx.fillStyle = R.rays[idx].col.col;
        ctx.fillRect(SCREENX - 4, yy, 8, 2);
      }
    }
    if (running && R.rays.length > 0){
      pulse += 0.035;
      var red = R.rays[0];
      var P = [R.start, R.I0, red.I1, [SCREENX, red.sy]];
      var segs = [];
      var total = 0;
      for (var s2 = 0; s2 < 3; s2++){
        var dx = P[s2+1][0]-P[s2][0], dy = P[s2+1][1]-P[s2][1];
        var L2 = Math.hypot(dx, dy); segs.push(L2); total += L2;
      }
      var dist = (pulse % 1) * total, acc = 0;
      var px, py;
      for (var s3 = 0; s3 < 3; s3++){
        if (dist <= acc + segs[s3] || s3 === 2){
          var d2 = Math.min(dist - acc, segs[s3]);
          var fr = segs[s3] ? d2 / segs[s3] : 0;
          px = P[s3][0] + (P[s3+1][0]-P[s3][0])*fr;
          py = P[s3][1] + (P[s3+1][1]-P[s3][1])*fr;
          break;
        }
        acc += segs[s3];
      }
      ctx.fillStyle = '#fbbf24';
      ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI*2); ctx.fill();
    }
    i1Val.textContent = R.i1 + '°';
    var Dred = R.rays[0] ? R.rays[0].Ddeg : 0;
    var Dvio = R.rays[R.rays.length-1] ? R.rays[R.rays.length-1].Ddeg : 0;
    var spread = Math.max(0, Dvio - Dred);
    window.simState.i1 = R.i1; window.simState.Dred = Dred; window.simState.Dvio = Dvio; window.simState.spread = spread;
    window.simState.time += 0.05;
    out.textContent = 'n أحمر = 1.52 | n بنفسجي = 1.60 | انحراف أحمر = ' + Dred.toFixed(1) + '° | انحراف بنفسجي = ' + Dvio.toFixed(1) + '° | انفراج الطيف = ' + spread.toFixed(1) + '°';
  }
  playBtn.addEventListener('click', function(){ running = !running; window.simState.running = running; playBtn.textContent = running ? 'إيقاف النبض' : 'تشغيل النبض'; });
  i1Slider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){ draw(); requestAnimationFrame(loop); }
  loop();
})();
